package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.Timestamp;
import java.math.*;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;
import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.learning.roadmaprating.v1.*;

/** Own-DB ratings and deterministic bounded ranking, independent of graph verification. */
final class RoadmapRatingStore {
 record Rating(UUID ratingId,UUID spaceId,UUID roadmapId,UUID principalId,long roadmapVersion,int score,String state,long version,String updatedAt){}
 record Mine(UUID spaceId,UUID roadmapId,long currentRoadmapVersion,boolean canRate,Rating rating){}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Rating snapshot){}
 record Summary(UUID spaceId,UUID roadmapId,long roadmapVersion,long ratingCount,long scoreSum,String averageScore,List<Long> starCounts){}
 record Ranked(int rank,UUID roadmapId,String title,long roadmapVersion,String verification,String updatedAt,long ratingCount,long scoreSum,String averageScore){}
 record Ranking(UUID spaceId,String sort,int limit,String generatedAt,List<Ranked> items){}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final PublicRoadmapStore roadmaps;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 RoadmapRatingStore(DataSource ds,PublicRoadmapStore roadmaps,Clock clock){sql=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.roadmaps=roadmaps;this.clock=clock;ids=new UuidV7(clock);}
 static String average(long sum,long count){return count==0?null:BigDecimal.valueOf(sum).divide(BigDecimal.valueOf(count),2,RoundingMode.HALF_UP).toPlainString();}
 private static void trace(String value){if(value==null||!value.matches("[0-9a-f]{32}")||value.equals("0".repeat(32)))throw RoadmapGraph.bad();}
 private Rating rating(java.sql.ResultSet rs)throws java.sql.SQLException{return new Rating(rs.getObject("rating_id",UUID.class),rs.getObject("space_id",UUID.class),rs.getObject("roadmap_id",UUID.class),rs.getObject("principal_id",UUID.class),rs.getLong("roadmap_version"),rs.getInt("score"),rs.getString("state"),rs.getLong("version"),rs.getTimestamp("updated_at").toInstant().toString());}
 Mine mine(UUID space,UUID id,UUID actor){RoadmapGraph.id(space);RoadmapGraph.id(id);RoadmapGraph.id(actor);var rows=sql.query("SELECT p.version AS current_version, EXISTS(SELECT 1 FROM roadmap_contribution c WHERE c.space_id=p.space_id AND c.roadmap_id=p.roadmap_id AND c.base_version=0 AND c.state='MERGED' AND c.author_id=?) AS is_author,r.* FROM public_roadmap p LEFT JOIN roadmap_rating r ON r.roadmap_id=p.roadmap_id AND r.space_id=p.space_id AND r.principal_id=? WHERE p.space_id=? AND p.roadmap_id=?",(rs,n)->new Mine(space,id,rs.getLong("current_version"),!rs.getBoolean("is_author"),rs.getObject("rating_id")==null?null:rating(rs)),actor,actor,space,id);if(rows.isEmpty())throw PublicRoadmapStore.error(HttpStatus.NOT_FOUND,"Published public roadmap required");return rows.getFirst();}
 List<Revision> history(UUID space,UUID id,UUID actor,long before,int limit){if(before<1||limit<1||limit>10)throw RoadmapGraph.bad();var mine=mine(space,id,actor);if(mine.rating()==null)return List.of();return sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM roadmap_rating_revision WHERE rating_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Rating.class)),mine.rating().ratingId(),before,limit);}
 Mine change(UUID space,UUID id,UUID actor,long expected,long roadmapVersion,int score,boolean retire,String trace){RoadmapGraph.id(space);RoadmapGraph.id(id);RoadmapGraph.id(actor);trace(trace);if(expected<0||!retire&&(roadmapVersion<1||score<1||score>5))throw RoadmapGraph.bad();return tx.execute(s->{var canonical=roadmaps.lock(space,id);var current=mine(space,id,actor);if(!current.canRate())throw PublicRoadmapStore.error(HttpStatus.FORBIDDEN,"Original publisher cannot rate own roadmap");var prior=current.rating();if((prior==null?0:prior.version())!=expected)throw PublicRoadmapStore.error(HttpStatus.PRECONDITION_FAILED,"Rating changed; reload before saving");if(!retire&&roadmapVersion!=canonical.version())throw PublicRoadmapStore.error(HttpStatus.CONFLICT,"Public roadmap changed; inspect current graph before rating");if(retire&&(prior==null||prior.state().equals("RETIRED")))return current;if(!retire&&prior!=null&&prior.state().equals("ACTIVE")&&prior.roadmapVersion()==roadmapVersion&&prior.score()==score)return current;
  String now=clock.instant().truncatedTo(ChronoUnit.MICROS).toString();var v=new Rating(prior==null?ids.next():prior.ratingId(),space,id,actor,retire?prior.roadmapVersion():roadmapVersion,retire?prior.score():score,retire?"RETIRED":"ACTIVE",prior==null?1:Math.addExact(prior.version(),1),now);
  if(prior==null)sql.update("INSERT INTO roadmap_rating VALUES (?,?,?,?,?,?,?,?,?)",v.ratingId(),space,id,actor,v.roadmapVersion(),v.score(),v.state(),v.version(),Timestamp.from(Instant.parse(now)));else sql.update("UPDATE roadmap_rating SET roadmap_version=?,score=?,state=?,version=?,updated_at=? WHERE rating_id=?",v.roadmapVersion(),v.score(),v.state(),v.version(),Timestamp.from(Instant.parse(now)),v.ratingId());
  UUID revision=ids.next();sql.update("INSERT INTO roadmap_rating_revision VALUES (?,?,?,?,?,?::jsonb)",revision,v.ratingId(),v.version(),actor,Timestamp.from(Instant.parse(now)),json.writeValueAsString(v));event(v,revision,trace);return mine(space,id,actor);
 });}
 Summary summary(UUID space,UUID id){RoadmapGraph.id(space);RoadmapGraph.id(id);var rows=sql.query("SELECT p.version,count(r.rating_id),coalesce(sum(r.score),0),count(r.rating_id) FILTER(WHERE r.score=1),count(r.rating_id) FILTER(WHERE r.score=2),count(r.rating_id) FILTER(WHERE r.score=3),count(r.rating_id) FILTER(WHERE r.score=4),count(r.rating_id) FILTER(WHERE r.score=5) FROM public_roadmap p LEFT JOIN roadmap_rating r ON r.roadmap_id=p.roadmap_id AND r.space_id=p.space_id AND r.roadmap_version=p.version AND r.state='ACTIVE' WHERE p.space_id=? AND p.roadmap_id=? GROUP BY p.version",(rs,n)->new Summary(space,id,rs.getLong(1),rs.getLong(2),rs.getLong(3),average(rs.getLong(3),rs.getLong(2)),List.of(rs.getLong(4),rs.getLong(5),rs.getLong(6),rs.getLong(7),rs.getLong(8))),space,id);if(rows.isEmpty())throw PublicRoadmapStore.error(HttpStatus.NOT_FOUND,"Published public roadmap required");return rows.getFirst();}
 Ranking ranking(UUID space,String sort,int limit){RoadmapGraph.id(space);if(sort==null||!Set.of("RATING","RATING_COUNT","RECENT").contains(sort)||limit<1||limit>100)throw RoadmapGraph.bad();String average="CASE WHEN count(r.rating_id)=0 THEN NULL ELSE sum(r.score)::numeric/count(r.rating_id) END";String order=switch(sort){case "RATING"->average+" DESC NULLS LAST,count(r.rating_id) DESC,p.roadmap_id";case "RATING_COUNT"->"count(r.rating_id) DESC,"+average+" DESC NULLS LAST,p.roadmap_id";case "RECENT"->"p.updated_at DESC,p.roadmap_id";default->throw RoadmapGraph.bad();};var items=sql.query("SELECT p.roadmap_id,p.title,p.version,p.updated_at,count(r.rating_id),coalesce(sum(r.score),0) FROM public_roadmap p LEFT JOIN roadmap_rating r ON r.space_id=p.space_id AND r.roadmap_id=p.roadmap_id AND r.roadmap_version=p.version AND r.state='ACTIVE' WHERE p.space_id=? GROUP BY p.roadmap_id,p.title,p.version,p.updated_at ORDER BY "+order+" LIMIT ?",(rs,n)->new Ranked(n+1,rs.getObject(1,UUID.class),rs.getString(2),rs.getLong(3),"REVIEWED",rs.getTimestamp(4).toInstant().toString(),rs.getLong(5),rs.getLong(6),average(rs.getLong(6),rs.getLong(5))),space,limit);return new Ranking(space,sort,limit,clock.instant().toString(),items);}
 private void event(Rating v,UUID revision,String trace){UUID event=ids.next();var now=Instant.parse(v.updatedAt());String type=v.state().equals("RETIRED")?"RoadmapRatingRetired":v.version()==1?"RoadmapRatingCreated":"RoadmapRatingUpdated";var payload=RoadmapRatingChangedV1.newBuilder().setRatingId(v.ratingId().toString()).setRoadmapId(v.roadmapId().toString()).setRoadmapVersion(v.roadmapVersion()).setPrincipalId(v.principalId().toString()).setVersion(v.version()).setState(v.state()).setScore(v.score()).setRevisionId(revision.toString()).setUpdatedAt(v.updatedAt()).build();var envelope=RoadmapRatingEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("learning-service").setAggregateType("RoadmapRating").setAggregateId(v.ratingId().toString()).setSpaceId(v.spaceId().toString()).setActorId(v.principalId().toString()).setTraceId(trace).setPayload(payload.toByteString()).build();sql.update("INSERT INTO outbox_event VALUES (?,'roadmap-rating',?,?,?,?, 'learning','roadmap-rating-events','1',?)",event,v.ratingId(),type,Timestamp.from(now),trace,envelope.toByteArray());}
}
